// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newDistributor) public {
        vm.assume(newDistributor != address(0));

        // The real owner (address(this)) attempts to call setRewardDistributor.
        // In the reference contract it succeeds; in the buggy contract
        // onlyOwner calls _checkOwner which calls owner() and compares to
        // _msgSender().  In the buggy contract owner() returns address(0)
        // so the require fails and the call reverts.
        bool referenceOk;
        try c.setRewardDistributor(newDistributor) {
            referenceOk = true;
        } catch {
            referenceOk = false;
        }

        // The reference contract MUST succeed (we are the owner).
        assertTrue(referenceOk);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address caller1, address caller2) public {
        vm.assume(caller1 != caller2);
        address owner1;
        address owner2;
        vm.prank(caller1);
        owner1 = c.owner();
        vm.prank(caller2);
        owner2 = c.owner();
        assertTrue(owner1 == owner2, "owner() should return same value for all callers");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(c));
        c.transferOwnership(newOwner);
        assertTrue(c.owner() != address(c));
    }
}
